template <typename Integer>
[[nodiscard]] QString quantityLabel(
    Integer count,
    const QString& singular,
    const QString& plural)
{
    return QStringLiteral("%1 %2")
        .arg(QString::number(count))
        .arg(count == 1 ? singular : plural);
}

struct TabularTextParseResult {
    QList<QStringList> rows;
    QString error;
};

[[nodiscard]] TabularTextParseResult
parseTabularText(
    const QString& text)
{
    TabularTextParseResult result;
    QStringList row;
    QString cell;
    bool fieldStarted = false;
    bool inQuotes = false;
    bool quoteClosed = false;
    const auto finishCell =
        [&] {
        row.push_back(cell);
        cell.clear();
        fieldStarted = false;
        quoteClosed = false;
    };
    const auto finishRow =
        [&] {
        finishCell();
        result.rows.push_back(row);
        row.clear();
    };

    for (qsizetype index = 0;
         index < text.size();
         ++index) {
        const QChar character =
            text.at(index);
        if (inQuotes) {
            if (character ==
                QLatin1Char('"')) {
                if (index + 1 <
                        text.size() &&
                    text.at(index + 1) ==
                        QLatin1Char('"')) {
                    cell +=
                        QLatin1Char('"');
                    ++index;
                } else {
                    inQuotes = false;
                    quoteClosed = true;
                }
            } else {
                cell += character;
            }
            continue;
        }
        if (quoteClosed) {
            if (character ==
                QLatin1Char('\t')) {
                finishCell();
                continue;
            }
            if (character ==
                QLatin1Char('\n')) {
                finishRow();
                continue;
            }
            result.error =
                QStringLiteral(
                    "unexpected text after a closing quote");
            result.rows.clear();
            return result;
        }
        if (!fieldStarted &&
            character ==
                QLatin1Char('"')) {
            fieldStarted = true;
            inQuotes = true;
            continue;
        }
        if (character ==
            QLatin1Char('\t')) {
            finishCell();
            continue;
        }
        if (character ==
            QLatin1Char('\n')) {
            finishRow();
            continue;
        }
        fieldStarted = true;
        cell += character;
    }
    if (inQuotes) {
        result.error =
            QStringLiteral(
                "unterminated quoted cell");
        result.rows.clear();
        return result;
    }
    finishRow();
    return result;
}

[[nodiscard]] QString tabularCellText(
    QString value)
{
    if (!value.contains(
            QLatin1Char('\t')) &&
        !value.contains(
            QLatin1Char('\n')) &&
        !value.contains(
            QLatin1Char('\r')) &&
        !value.contains(
            QLatin1Char('"'))) {
        return value;
    }
    value.replace(
        QLatin1Char('"'),
        QStringLiteral("\"\""));
    return QStringLiteral("\"%1\"")
        .arg(value);
}

