    connect(enumView_, &QWidget::customContextMenuRequested, this, [this](const QPoint& position) {
        if (tableInteractionBlocked_ ||
            !commitActiveEditor()) {
            return;
        }
        const QModelIndex index = enumView_->indexAt(position);
        if (!index.isValid()) {
            return;
        }
        if (index.data(addRowRole).toBool()) {
            const std::unique_ptr<QMenu> ownedMenu(WorkbenchControls::menu(this));
            QMenu& menu = *ownedMenu;
            menu.setObjectName(
                QStringLiteral("enumAddRowContextMenu"));
            QAction* add =
                menu.addAction(
                    QStringLiteral("Add Enum Value"));
            add->setObjectName(
                QStringLiteral(
                    "addEnumValueContextAction"));
            if (menu.exec(
                    enumView_->viewport()
                        ->mapToGlobal(position)) == add) {
                addEnumValue();
            }
            return;
        }
        const QModelIndex
            contextCurrent =
                prepareContextSelection(
                    enumView_, index);
        enumView_->selectionModel()
            ->setCurrentIndex(
                contextCurrent,
                QItemSelectionModel::
                    NoUpdate);
        lastCommandView_ =
            enumView_;
        updateEditActions();
        const std::string id = index.data(objectIdRole).toString().toUtf8().toStdString();
        if (id.empty()) {
            return;
        }
        const auto* workspace = controller_.workspace();
        const auto* enumValue =
            workspace == nullptr ? nullptr : regmap::findEnumValue(*workspace, id);
        if (enumValue == nullptr) {
            return;
        }
        const std::size_t selectedCount =
            selectedEnumValueIds()
                .size();
        const std::unique_ptr<QMenu> ownedMenu(WorkbenchControls::menu(this));
        QMenu& menu = *ownedMenu;
        menu.setObjectName(QStringLiteral("enumContextMenu"));
        menu.setToolTipsVisible(true);
        menu.addAction(copyAction_);
        menu.addAction(pasteAction_);
        menu.addSeparator();
        QAction* remove =
            menu.addAction(
                selectedCount > 1
                    ? QStringLiteral(
                          "Delete %1 Selected Enum Values")
                          .arg(
                              selectedCount)
                    : QStringLiteral(
                          "Delete Enum Value"));
        remove->setObjectName(QStringLiteral("deleteEnumValueAction"));
        QAction* chosen =
            menu.exec(
                enumView_->viewport()
                    ->mapToGlobal(
                        position));
        lastCommandView_ =
            enumView_;
        updateEditActions();
        if (chosen != remove) {
            if (chosen == nullptr) {
                QTimer::singleShot(
                    0,
                    enumView_,
                    [this,
                     view = enumView_] {
                        if (QApplication::
                                activePopupWidget() !=
                            nullptr) {
                            return;
                        }
                        view->window()
                            ->activateWindow();
                        view->setFocus(
                            Qt::
                                OtherFocusReason);
                        lastCommandView_ =
                            view;
                        updateEditActions();
                    });
            }
            return;
        }
        const auto selectedValues =
            selectedEnumValueIds();
        if (selectedValues.size() >
            1) {
            deleteSelectedEnumValues(
                selectedValues);
        } else {
            deleteEnumValue(id);
        }
    });
